#include <cassert>
#include <chrono>
#include <filesystem>
#include "phase4_live_test_support.hpp"
int main(){using namespace phase4_live_test;auto e=environment("task-f7l-restart");auto m=matrix(e);auto suffix=std::to_string(std::chrono::steady_clock::now().time_since_epoch().count());auto path=(std::filesystem::temp_directory_path()/("taskflow-f7l-restart-"+suffix+".sqlite")).string();DeterministicExecutor x;{SQLiteRoleCertificationStore s(path);RoleCertificationCheckpoint cp;cp.metadata=e.metadata;cp.workflow_id="restart-live";cp.environment_digest=role_environment_digest(e);cp.matrix_digest=role_live_matrix_digest(m);cp.updated_at="2026-08-10T01:00:00Z";assert(s.create(cp));auto first=x.execute({e,m,m.cells[0],{}});cp.cells.push_back(first);cp.next_cell=1;cp.revision=2;assert(s.compare_exchange(cp,1));}{SQLiteRoleCertificationStore s(path);RoleLiveCertificationWorkflow w(s,x);auto r=w.run(e,m,options("restart-live"));assert(r.state==RoleCertificationState::Certified&&r.report&&r.report->cells.size()==m.cells.size());assert(s.load_report("tenant-live","restart-live"));}std::filesystem::remove(path);std::filesystem::remove(path+"-wal");std::filesystem::remove(path+"-shm");return 0;}
